CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,sku VARCHAR(80) NOT NULL,barcode VARCHAR(120) NULL,name VARCHAR(250) NOT NULL,brand VARCHAR(120) NULL,category VARCHAR(120) NULL,unit VARCHAR(40) NOT NULL DEFAULT 'عدد',sale_price DECIMAL(20,2) NOT NULL DEFAULT 0,min_stock DECIMAL(20,4) NOT NULL DEFAULT 0,reorder_point DECIMAL(20,4) NOT NULL DEFAULT 0,track_batch TINYINT(1) NOT NULL DEFAULT 0,track_expiry TINYINT(1) NOT NULL DEFAULT 0,catch_weight TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,is_deleted TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_product_company_sku(company_id,sku),KEY ix_product_name(company_id,name),KEY ix_product_barcode(company_id,barcode),CONSTRAINT fk_product_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS warehouses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,code VARCHAR(50) NOT NULL,name VARCHAR(200) NOT NULL,warehouse_type ENUM('GENERAL','COLD','FROZEN','QUARANTINE','TRANSIT') NOT NULL DEFAULT 'GENERAL',allow_negative TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_wh_company_code(company_id,code),CONSTRAINT fk_wh_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_wh_branch FOREIGN KEY(branch_id) REFERENCES branches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS inventory_balances (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,batch_no VARCHAR(100) NULL,expiry_date DATE NULL,on_hand_qty DECIMAL(20,4) NOT NULL DEFAULT 0,reserved_qty DECIMAL(20,4) NOT NULL DEFAULT 0,quarantine_qty DECIMAL(20,4) NOT NULL DEFAULT 0,damaged_qty DECIMAL(20,4) NOT NULL DEFAULT 0,average_cost DECIMAL(20,4) NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_inv_balance(company_id,warehouse_id,product_id,batch_no,expiry_date),KEY ix_inv_product(company_id,product_id),CONSTRAINT fk_inv_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_inv_wh FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CONSTRAINT fk_inv_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS inventory_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,warehouse_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,movement_date DATETIME NOT NULL,movement_type ENUM('RECEIPT','ISSUE','TRANSFER_IN','TRANSFER_OUT','RETURN_IN','RETURN_OUT','ADJUSTMENT_IN','ADJUSTMENT_OUT','COUNT') NOT NULL,quantity DECIMAL(20,4) NOT NULL,unit_cost DECIMAL(20,4) NOT NULL DEFAULT 0,batch_no VARCHAR(100) NULL,expiry_date DATE NULL,source_type VARCHAR(80) NULL,source_id BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY ix_mov_product_date(company_id,product_id,movement_date),KEY ix_mov_source(source_type,source_id),CONSTRAINT fk_mov_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_mov_wh FOREIGN KEY(warehouse_id) REFERENCES warehouses(id),CONSTRAINT fk_mov_product FOREIGN KEY(product_id) REFERENCES products(id),CONSTRAINT fk_mov_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS sales_invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,invoice_no VARCHAR(80) NOT NULL,invoice_date DATE NOT NULL,posting_date DATE NULL,due_date DATE NULL,delivery_date DATE NULL,customer_party_id BIGINT UNSIGNED NOT NULL,status ENUM('DRAFT','WAITING_APPROVAL','APPROVED','RESERVED','PICKING','PACKING','READY_TO_SHIP','DISPATCHED','DELIVERED','PARTIAL_DELIVERY','OUTSTANDING','OVERDUE','PAID','CANCELLED','RETURNED') NOT NULL DEFAULT 'DRAFT',gross_total DECIMAL(20,2) NOT NULL DEFAULT 0,discount_total DECIMAL(20,2) NOT NULL DEFAULT 0,tax_total DECIMAL(20,2) NOT NULL DEFAULT 0,net_total DECIMAL(20,2) NOT NULL DEFAULT 0,outstanding_amount DECIMAL(20,2) NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NOT NULL,posted_at DATETIME NULL,is_void TINYINT(1) NOT NULL DEFAULT 0,void_reason VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_sales_invoice(company_id,invoice_no),KEY ix_sales_date(company_id,invoice_date),KEY ix_sales_customer(customer_party_id,status),CONSTRAINT fk_sales_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_sales_customer FOREIGN KEY(customer_party_id) REFERENCES parties(id),CONSTRAINT fk_sales_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS sales_invoice_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,qty DECIMAL(20,4) NOT NULL,unit_price DECIMAL(20,2) NOT NULL,discount_amount DECIMAL(20,2) NOT NULL DEFAULT 0,tax_amount DECIMAL(20,2) NOT NULL DEFAULT 0,line_total DECIMAL(20,2) NOT NULL,CONSTRAINT fk_sales_line_invoice FOREIGN KEY(invoice_id) REFERENCES sales_invoices(id) ON DELETE CASCADE,CONSTRAINT fk_sales_line_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS purchase_invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,invoice_no VARCHAR(80) NOT NULL,invoice_date DATE NOT NULL,supplier_party_id BIGINT UNSIGNED NOT NULL,status ENUM('DRAFT','MATCH_PENDING','MATCH_EXCEPTION','APPROVED','OUTSTANDING','PAID','VOID') NOT NULL DEFAULT 'DRAFT',gross_total DECIMAL(20,2) NOT NULL DEFAULT 0,discount_total DECIMAL(20,2) NOT NULL DEFAULT 0,tax_total DECIMAL(20,2) NOT NULL DEFAULT 0,net_total DECIMAL(20,2) NOT NULL DEFAULT 0,outstanding_amount DECIMAL(20,2) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_purchase_invoice(company_id,invoice_no),KEY ix_purchase_supplier(supplier_party_id,status),CONSTRAINT fk_purchase_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_purchase_supplier FOREIGN KEY(supplier_party_id) REFERENCES parties(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS purchase_invoice_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,description VARCHAR(500) NULL,qty DECIMAL(20,4) NOT NULL DEFAULT 1,unit_price DECIMAL(20,2) NOT NULL DEFAULT 0,line_total DECIMAL(20,2) NOT NULL DEFAULT 0,CONSTRAINT fk_purchase_line_invoice FOREIGN KEY(invoice_id) REFERENCES purchase_invoices(id) ON DELETE CASCADE,CONSTRAINT fk_purchase_line_product FOREIGN KEY(product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;